public static void main(String[] args) {
    long n = Long.parseLong(args[0]);
    long cube = 0L;
    for (long i = 1L; i * i * i <= n; i++) {
        String s = i * i * i + "";
        if (check(s) == true) {
            cube = i * i * i;
        }
    }
    System.out.println(cube);
}

public static boolean check(String s) {
    int len = s.length();
    for (int i = 0; i < len / 2; i++) {
        if (s.charAt(i) != s.charAt(len - i - 1)) {
            return false;
        }
    }
    return true;
}
